package cn.haiduo;
import cn.haiduo.inventory.InventoryService;
import cn.haiduo.platform.*;
import java.util.*;
import java.time.Instant;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.flywaydb.core.Flyway;
import static org.junit.jupiter.api.Assertions.*;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="RUN_SYNC_TESTS",matches="true")
class SyncContainerTest {
 @Test void sameSecondAuthoritativeChangeStillAppliesOnce(){sync();apply(update("2026-01-03T00:00:00Z","80.00",false));UUID id=order();tx.executeWithoutResult(s->inventory.transition(tenant,id,"reserve"));for(int n=0;n<10;n++)apply(update("2026-01-03T00:00:00Z","0",true));assertEquals("CANCELLED",db.queryForObject("select status from sales_order where id=?",String.class,id));assertEquals(0,db.queryForObject("select reserved from inventory where tenant_id=?",Integer.class,tenant));assertEquals(2,db.queryForObject("select count(*) from inventory_movement where tenant_id=?",Integer.class,tenant));}
 static PostgreSQLContainer pg;static JdbcTemplate db;static TransactionTemplate tx;UUID tenant,store,sku;SyncProcessor processor;InventoryService inventory;
 @BeforeAll static void start(){pg=new PostgreSQLContainer("postgres:17.6").withDatabaseName("haiduo").withUsername("haiduo").withPassword("test-password");pg.start();var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());Flyway.configure().dataSource(ds).load().migrate();db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop(){if(pg!=null)pg.stop();}
 @BeforeEach void setup(){tenant=UUID.randomUUID();store=UUID.randomUUID();sku=UUID.randomUUID();db.update("insert into tenant values(?,?)",tenant,"sync-test");db.update("insert into warehouse values(?,?::uuid,'default')",tenant,"00000000-0000-0000-0000-000000000001");db.update("insert into product(id,tenant_id,name) values(?,?,'test')",sku,tenant);db.update("insert into sku values(?,?,'DEMO-BAG','test',200,?)",sku,tenant,sku);db.update("insert into inventory(tenant_id,sku_id,on_hand,reserved) values(?,?,100,0)",tenant,sku);db.update("insert into store values(?,?,'mock','MOCK','MOCK')",store,tenant);inventory=new InventoryService(db);processor=new SyncProcessor(db,null,inventory);}
 void sync(){tx.executeWithoutResult(s->{try{processor.process(tenant,"STORE_SYNC",store.toString());}catch(Exception e){throw new IllegalStateException(e);}});}
 UUID order(){return db.queryForObject("select id from sales_order where tenant_id=?",UUID.class,tenant);}
 PlatformConnector.Order update(String time,String net,boolean cancel){return new PlatformConnector.Order("MOCK-SYNC-001",Instant.parse(time),"USD",new BigDecimal(net),"PAID",cancel?"REFUNDED":"PARTIAL",cancel,"UNFULFILLED",List.of(new PlatformConnector.Item("MOCK-BAG","DEMO-BAG",1)));}
 void apply(PlatformConnector.Order order){tx.executeWithoutResult(s->processor.upsert(tenant,store,"mock",UUID.fromString("00000000-0000-0000-0000-000000000001"),true,order));}
 @Test void repeatedMockSyncCreatesOneOrder(){for(int i=0;i<10;i++)sync();assertEquals(1,db.queryForObject("select count(*) from sales_order where tenant_id=?",Integer.class,tenant));assertEquals(1,db.queryForObject("select count(*) from order_item where tenant_id=?",Integer.class,tenant));assertEquals(0,db.queryForObject("select reserved from inventory where tenant_id=?",Integer.class,tenant));}
 @Test void olderEventsDoNotOverwriteMoneyOrCost(){sync();db.update("update sku set cost=999 where tenant_id=?",tenant);apply(update("2026-01-03T00:00:00Z","80.00",false));apply(update("2026-01-02T00:00:00Z","10.00",false));assertEquals(new BigDecimal("80.0000"),db.queryForObject("select net from sales_order where tenant_id=?",BigDecimal.class,tenant));assertEquals(new BigDecimal("7.20000000"),db.queryForObject("select rate from sales_order where tenant_id=?",BigDecimal.class,tenant));assertEquals(new BigDecimal("200.0000"),db.queryForObject("select unit_cost_cny from order_item where tenant_id=?",BigDecimal.class,tenant));}
 @Test void cancellationReleasesButShippedNeverRestocks(){sync();UUID id=order();tx.executeWithoutResult(s->inventory.transition(tenant,id,"reserve"));apply(update("2026-01-03T00:00:00Z","0",true));assertEquals(0,db.queryForObject("select reserved from inventory where tenant_id=?",Integer.class,tenant));assertEquals("CANCELLED",db.queryForObject("select status from sales_order where id=?",String.class,id));}
 @Test void cancellationAfterShippingRequiresReview(){sync();UUID id=order();tx.executeWithoutResult(s->{inventory.transition(tenant,id,"reserve");inventory.transition(tenant,id,"ship");});apply(update("2026-01-03T00:00:00Z","0",true));assertEquals(99,db.queryForObject("select on_hand from inventory where tenant_id=?",Integer.class,tenant));assertTrue(db.queryForObject("select sync_review_required from sales_order where id=?",Boolean.class,id));assertEquals("SHIPPED",db.queryForObject("select status from sales_order where id=?",String.class,id));}
 @Test void externallyFulfilledOrderDoesNotDeductLocalStock(){var external=new PlatformConnector.Order("EXTERNAL-1",Instant.parse("2026-01-03T00:00:00Z"),"USD",new BigDecimal("100"),"PAID","NONE",false,"FULFILLED",List.of(new PlatformConnector.Item("MOCK-BAG","DEMO-BAG",1)));apply(external);assertEquals("SHIPPED",db.queryForObject("select status from sales_order where tenant_id=?",String.class,tenant));assertTrue(db.queryForObject("select externally_fulfilled from sales_order where tenant_id=?",Boolean.class,tenant));assertEquals(100,db.queryForObject("select on_hand from inventory where tenant_id=?",Integer.class,tenant));}
 @Test void partialPlatformFulfillmentBlocksLocalReservation(){var external=new PlatformConnector.Order("PARTIAL-1",Instant.parse("2026-01-03T00:00:00Z"),"USD",new BigDecimal("100"),"PAID","NONE",false,"PARTIALLY_FULFILLED",List.of(new PlatformConnector.Item("MOCK-BAG","DEMO-BAG",1)));apply(external);assertThrows(IllegalStateException.class,()->tx.executeWithoutResult(s->inventory.transition(tenant,order(),"reserve")));assertEquals(0,db.queryForObject("select reserved from inventory where tenant_id=?",Integer.class,tenant));}
 @Test void webhookRawSignatureBindingAndDuplicateIntake()throws Exception{db.update("update store set platform='SHOPIFY',connection_status='CONNECTED' where tenant_id=? and id=?",tenant,store);String shop="fixture-"+tenant+".myshopify.com";db.update("insert into platform_connection(tenant_id,store_id,shop_domain,access_cipher,scopes) values(?,?,?,'TEST-NOT-A-TOKEN','read_orders')",tenant,store,shop);String secret="webhook-test-secret";var controller=new ShopifyController(null,null,db,new org.springframework.mock.env.MockEnvironment().withProperty("SHOPIFY_CLIENT_SECRET",secret));byte[] body="{\"admin_graphql_api_id\":\"gid://shopify/Order/1\"}".getBytes(java.nio.charset.StandardCharsets.UTF_8);String signature=Base64.getEncoder().encodeToString(PlatformCrypto.hmac(secret,body)),event=UUID.randomUUID().toString();for(int i=0;i<10;i++){var request=webhook(body,shop,signature,UUID.randomUUID().toString(),event);tx.executeWithoutResult(s->{try{controller.webhook(request);}catch(Exception e){throw new IllegalStateException(e);}});}assertEquals(1,db.queryForObject("select count(*) from webhook_inbox where tenant_id=?",Integer.class,tenant));assertEquals(1,db.queryForObject("select count(*) from outbox_event where tenant_id=? and kind='SHOPIFY_WEBHOOK'",Integer.class,tenant));var tampered=webhook((" "+new String(body,java.nio.charset.StandardCharsets.UTF_8)).getBytes(java.nio.charset.StandardCharsets.UTF_8),shop,signature,UUID.randomUUID().toString(),UUID.randomUUID().toString());var failure=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->controller.webhook(tampered));assertEquals(401,failure.getStatusCode().value());var unknown=webhook(body,"unbound.myshopify.com",signature,UUID.randomUUID().toString(),UUID.randomUUID().toString());assertEquals(401,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->controller.webhook(unknown)).getStatusCode().value());}
 org.springframework.mock.web.MockHttpServletRequest webhook(byte[] body,String shop,String signature,String delivery,String event){var request=new org.springframework.mock.web.MockHttpServletRequest();request.setContent(body);request.addHeader("X-Shopify-Shop-Domain",shop);request.addHeader("X-Shopify-Hmac-Sha256",signature);request.addHeader("X-Shopify-Webhook-Id",delivery);request.addHeader("X-Shopify-Event-Id",event);request.addHeader("X-Shopify-Topic","orders/updated");request.addParameter("tenant_id",UUID.randomUUID().toString());return request;}
 @Test void oauthStateSignatureEncryptedTokensAndRefresh()throws Exception{db.update("update store set platform='SHOPIFY',connection_status='DISABLED' where tenant_id=? and id=?",tenant,store);db.update("insert into membership values('oauth-tester',?,'ADMIN')",tenant);String key=Base64.getEncoder().encodeToString(new byte[32]),secret="oauth-client-secret",shop="oauth-"+tenant+".myshopify.com";var calls=new java.util.concurrent.atomic.AtomicInteger();ShopifyHttp transport=new ShopifyHttp(){@Override public com.fasterxml.jackson.databind.JsonNode form(java.net.URI uri,Map<String,String> fields)throws Exception{int n=calls.incrementAndGet();if(n==1)assertEquals("1",fields.get("expiring"));else{assertEquals("refresh_token",fields.get("grant_type"));assertEquals("refresh-1",fields.get("refresh_token"));}return new com.fasterxml.jackson.databind.ObjectMapper().readTree("{\"access_token\":\"access-"+n+"\",\"refresh_token\":\"refresh-"+n+"\",\"expires_in\":3600,\"scope\":\"read_orders\"}");}};var env=new org.springframework.mock.env.MockEnvironment().withProperty("SHOPIFY_CLIENT_ID","client-test").withProperty("SHOPIFY_CLIENT_SECRET",secret).withProperty("TOKEN_ENCRYPTION_KEY",key).withProperty("SHOPIFY_REDIRECT_URI","http://localhost:8084/api/shopify/callback");var auth=new ShopifyAuthorization(env,db,transport);var session=new org.springframework.mock.web.MockHttpSession();assertTrue(auth.start(tenant,store,shop,session,"oauth-tester").get("url").contains("scope=read_orders"));var state=(Map<?,?>)session.getAttribute("shopify.oauth");var request=new org.springframework.mock.web.MockHttpServletRequest();request.addParameter("shop",shop);request.addParameter("state",state.get("state").toString());request.addParameter("code","test-code");request.addParameter("timestamp",String.valueOf(java.time.Instant.now().getEpochSecond()));String message=request.getParameterMap().entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->e.getKey()+"="+e.getValue()[0]).collect(java.util.stream.Collectors.joining("&"));request.addParameter("hmac",HexFormat.of().formatHex(PlatformCrypto.hmac(secret,message.getBytes(java.nio.charset.StandardCharsets.UTF_8))));tx.executeWithoutResult(s->{try{auth.callback(request,session,"oauth-tester");}catch(Exception e){throw new IllegalStateException(e);}});assertNull(session.getAttribute("shopify.oauth"));String cipher=db.queryForObject("select access_cipher from platform_connection where tenant_id=?",String.class,tenant);assertNotEquals("access-1",cipher);assertEquals("access-1",PlatformCrypto.decrypt(key,cipher));assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->auth.callback(request,session,"oauth-tester")).getStatusCode().value());db.update("update platform_connection set expires_at=now()-interval '1 minute' where tenant_id=?",tenant);tx.executeWithoutResult(s->{try{auth.connector(tenant,store);}catch(Exception e){throw new IllegalStateException(e);}});assertEquals(2,calls.get());assertEquals("access-2",PlatformCrypto.decrypt(key,db.queryForObject("select access_cipher from platform_connection where tenant_id=?",String.class,tenant)));}
}
